modes=['Orientation and setup','Concept development','Guided laboratory','Guided laboratory','Applied practice','Operations and measurement','Troubleshooting laboratory','Safety and quality review','Integration and documentation','Assessment and presentation']
labels=['Foundations and Vocabulary','Applied Baseline Lab','Architecture and Components','Configuration Lab','Design and Technique','Operations and Measurement','Troubleshooting and Failure Modes','Safety, Quality, and Verification']
def difficulty(n): return 'foundation' if n<=30 else 'foundation-to-intermediate' if n<=80 else 'intermediate' if n<=130 else 'intermediate-to-advanced' if n<=170 else 'capstone'
def slug(s): return ''.join(c.lower() if c.isalnum() else '-' for c in s).strip('-').replace('--','-')[:62]

def build(key,cfg):
 days=[]; n=0
 for pn,(phase,themes_s,phase_tools_s) in enumerate(cfg['phases'],1):
  themes=themes_s.split('|'); phase_tools=phase_tools_s.split('|'); assert len(themes)==4
  for slot in range(1,11):
   n+=1
   if slot<=8:
    theme=themes[(slot-1)//2]; topic=f'{theme.title()} — {labels[slot-1]}'
    objective=(f'Explain and demonstrate {theme} through an authorized baseline, measurable check, documented failure mode, and independent verification.' if slot%2 else f'Complete a supervised applied lab for {theme}, record expected versus observed results, diagnose one controlled fault, and restore the approved state.')
   elif slot==9:
    topic=f'{phase.replace("Phase ","")} — Integration, Documentation, and Handover'; objective=f'Integrate the four {phase.lower()} skill areas into one reproducible workflow, diagram, checklist, evidence pack, and handover note.'
   else:
    topic=f'{phase.replace("Phase ","")} — Assessment Project'; objective=f'Plan, execute, verify, present, and safely close an assessment project covering the complete {phase.lower()} phase.'
   if n==1: topic=cfg['day1']; objective=cfg['day1_obj']
   tools=list(dict.fromkeys(cfg['base_tools'][:2]+phase_tools))
   s=slug(topic)
   equipment=key in {'Intercom','Lighting','LiveSound','ScreensVideo'}
   procedures=[f'Review the Day {n} scope, prerequisite from Day {n-1}, and supervisor instructions before touching software, accounts, cables, power, rigging, networks, or equipment.','Confirm the authorized lab/equipment boundary, owner, asset IDs, workspace condition, backup/rollback state, emergency procedure, and any PPE or spotter requirement.',f'Verify only the approved tools for today: {", ".join(tools)}. Record versions, firmware, serial/asset references, calibration status, or configuration as relevant. Avoid unnecessary installation or updates.',f'Create Day_{n:03d}_{s.replace("-","_")} with evidence, diagrams or src, checklists or tests, output, and report folders.','Capture a privacy-reviewed baseline photograph/screenshot and record expected result, measurement units, acceptance limit, and stop condition.',f'Complete the practical objective: {objective}','Introduce or analyze only an approved controlled fault/edge case. Troubleshoot systematically, preserve evidence, and return the lab/equipment to its approved state.','Verify independently through a second instrument/path/test, clean rerun, configuration comparison, peer check, or supervisor sign-off. Distinguish evidence from proof.','Complete the discipline safety/ethics checklist, inventory/custody or cleanup check, and a professional report with honest limitations and assistance disclosure.']
   rules=[cfg['safety'],'Use only assigned labs, equipment, data, accounts, frequencies, networks, repositories, venues, and test targets. Stop if authorization or ownership is unclear.','Do not expose secrets, private/client data, personal communications, production identifiers, unsafe images, or unrelated backgrounds in code, prompts, repositories, recordings, photographs, screenshots, or reports.','Never bypass guards, interlocks, PPE, access controls, rated loads, electrical protection, change approval, licences, or vendor limits. Do not improvise unsafe adapters, rigging, mains power, scans, exploits, or public exposure.','Use approved rollback, mute/power-down, backup, snapshot, restore, isolation, or safe-strike procedures before and after changes. Report accidental exposure, injury risk, damage, data loss, or boundary crossing immediately.','Disclose AI/tool assistance and verify every generated instruction, calculation, configuration, claim, measurement, and recommendation. Record time, errors, troubleshooting, incidents, limitations, and equipment condition honestly.']
   outcomes=[f'Explain {topic} in clear professional language.',f'Use {", ".join(tools[:3])} to complete the objective inside the approved boundary.',f'Produce measurable, independently verified evidence for: {objective}','Apply Beyond safety, ethics, quality, documentation, rollback, and human-approval standards.']
   questions=[f'Can you explain {topic} to a supervisor in under two minutes without reading?',f'What evidence proves that you completed “{objective}” rather than merely watching or copying a result?','Which safety, privacy, security, electrical, mechanical, hearing, data-quality, operational, or authorization failure is most relevant today?','What measurement or acceptance criterion did you use, and what are its limitations?','How did you independently verify the result and restore the approved state?','What would you check first if the demonstration failed five minutes before review?','Why is the result ready—or not ready—for real use, and who must approve the next action?']
   ev=[{'filename':f'day-{n:03d}_{s}_baseline.png','requirement':'Privacy-reviewed baseline showing the authorized workspace, isolation/boundary, assigned tools or equipment, and safe starting state.'},{'filename':f'day-{n:03d}_{s}_practical.zip','requirement':'Configurations, code, diagrams, checklists, measurements, tests, and outputs needed to reproduce the work; exclude secrets and unauthorized data.'},{'filename':f'day-{n:03d}_{s}_verification.txt','requirement':'Expected versus observed result, acceptance criterion, and independent second test, measurement, peer review, or supervisor sign-off.'},{'filename':f'day-{n:03d}_{s}_safety-restoration.txt','requirement':'Completed safety/ethics check plus proof of rollback, cleanup, inventory/custody, safe power-down/strike, or restored lab state as applicable.'},{'filename':f'day-{n:03d}_{s}_report.pdf','requirement':'Professional report covering scope, concepts, tools/equipment, procedure, measurements, results, risks, verification, troubleshooting, limitations, restoration, assistance disclosure, and references.'}]
   days.append({'day':n,'day_code':f'DAY_{n:03d}','phase_number':pn,'phase':phase,'mode':modes[slot-1],'topic':topic,'difficulty':difficulty(n),'estimated_time_hours':8,'tools':tools,'objective':objective,'learning_outcomes':outcomes,'core_concepts':[phase]+themes,'practical_procedure':procedures,'safety_ethics_and_beyond_lab_rules':rules,'self_check_questions':questions,'evidence_checklist':ev,'required_submission':('Assessment demonstration, reproducible project/equipment package, verification and restoration evidence, safety review, and professional report.' if slot==10 else 'Baseline evidence, completed practical artifact, independent verification, safety/restoration record, and short professional report.'),'prerequisite':('Program admission, assigned authorized workstation/equipment, and approved lab or venue boundary.' if n==1 else f'Completion of Day {n-1}, with unresolved safety, equipment, data, access, or restoration issues escalated before continuing.'),'report_sections':['Title and metadata','Objective, scope, authorization, and boundary','Concepts in the student’s own words','Environment, equipment, software, versions, and asset references','Inputs, diagrams, and baseline state','Procedure and change record','Measurements, results, and acceptance criteria','Independent verification','Safety, ethics, security, privacy, quality, and human approval','Troubleshooting and rollback','Cleanup, restoration, custody, and residual risk','Limitations and next step','AI/tool assistance disclosure','Official/vendor references']})
 assert len(days)==180 and len({d['topic'] for d in days})==180
 program={'program_title':f"Beyond {cfg['name']} Internship — 180-Day Program",'program_version':'1.0','daily_duration_hours':8,'total_days':180,'total_guided_hours':1440,'purpose':f"Prepare interns to perform {cfg['name'].lower()} work safely, ethically, measurably, reproducibly, and professionally under Beyond supervision.",'source_day_1_handbook':f"{cfg['folder']}_Day_001_Student_Handbook.docx",'global_rules':[cfg['safety'],'Work only inside authorized boundaries and on assigned assets.','Capture evidence during work; preserve prior evidence and restore the approved state.','Use official/vendor sources, approved tools, rated hardware, valid licences, and qualified supervision.','Protect secrets, personal/client data, recordings, equipment details, and production information.','Document measurements, uncertainty, errors, troubleshooting, time, assistance, incidents, and limitations honestly.'],'phases':[{'phase_number':i+1,'name':x[0],'days':f'{i*10+1}-{i*10+10}'} for i,x in enumerate(cfg['phases'])],'days':days}
 stem=f"Beyond_{key}_Internship_180_Day_Program"; jp=OUT/f'{stem}.json'; mp=OUT/f'{stem}.md'; cp=OUT/f'Beyond_{key}_Internship_180_Day_Index.csv'
 jp.write_text(json.dumps(program,indent=2,ensure_ascii=False),encoding='utf-8')
 md=[f"# {program['program_title']}",'',f"**Duration:** 180 days · 8 hours per day · 1,440 guided hours",'',program['purpose'],'','## Program-wide safety and professional rules','']+[f'- {x}' for x in program['global_rules']]+['','## Program phases','']+[f"- **{x['name']}** — Days {x['days']}" for x in program['phases']]
 for d in days:
  md+=['','---','',f"# STUDY NOTES — Day {d['day']}: {d['mode']}: {d['topic']}",'',f"Beyond {cfg['name']} internship notes prepare students to apply **{d['topic']}** safely, ethically, measurably, and professionally under human supervision.",'','## 1. DAY FOCUS','',f"**Mode:** {d['mode']}  ",f"**Topic:** {d['topic']}  ",f"**Phase:** {d['phase']}  ",f"**Difficulty:** {d['difficulty']} · **Estimated time:** 8h  ",f"**Tools for this day:** {', '.join(d['tools'])}",'',f"**Objective:** {d['objective']}",'','## 2. LEARNING OUTCOMES','']+[f'- {x}' for x in d['learning_outcomes']]+['','## 3. CORE CONCEPTS','',f"**Topic focus:** {d['topic']}. Define meaningful professional concepts rather than splitting the title into isolated words. Connect every concept to an observable action, measurement/control, evidence item, and failure mode.",'','**Key terms and ideas to define in the report:**','']+[f'- {x}' for x in d['core_concepts']]+['','## 4. PRACTICAL PROCEDURE','',f"**Prerequisite:** {d['prerequisite']}",'']+[f'{i}. {x}' for i,x in enumerate(d['practical_procedure'],1)]+['','## 5. SAFETY, ETHICS, AND BEYOND LAB RULES','']+[f'- {x}' for x in d['safety_ethics_and_beyond_lab_rules']]+['','## 6. SELF-CHECK QUESTIONS','']+[f'{i}. {x}' for i,x in enumerate(d['self_check_questions'],1)]+['','## 7. EVIDENCE CHECKLIST','','- Collect evidence while working—not only at the end.','- Use clear filenames and remove secrets, personal/client information, notifications, and unrelated content.']+[f"- **{e['filename']}** — {e['requirement']}" for e in d['evidence_checklist']]+['',f"**Required submission:** {d['required_submission']}",'','**Pass tip:** Supervisors assess correct technique, measurable evidence, safety, honest troubleshooting, verified restoration, and professional documentation—not a perfect first attempt.','',f"**Required report sections:** {'; '.join(d['report_sections'])}."]
 mp.write_text('\n'.join(md)+'\n',encoding='utf-8')
 fields=['day','day_code','phase_number','phase','mode','topic','difficulty','estimated_time_hours','tools','objective','required_submission']
 with cp.open('w',newline='',encoding='utf-8') as f:
  w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
  for d in days:w.writerow({x:(' | '.join(d[x]) if x=='tools' else d[x]) for x in fields})
 zp=OUT/f'{stem}_Package.zip'
 with zipfile.ZipFile(zp,'w',zipfile.ZIP_DEFLATED) as z:
  for f in [jp,mp,cp]:z.write(f,f.name)
 return [jp,mp,cp,zp],program

files=[]; all_programs={}
for key,cfg in P.items():
 fs,prog=build(key,cfg);files+=fs;all_programs[key]=prog;print(key,len(prog['days']),len(prog['phases']))
manifest=OUT/'Beyond_All_Internships_180_Day_Manifest.json';manifest.write_text(json.dumps({'program_count':len(P),'total_days':sum(len(x['days']) for x in all_programs.values()),'programs':[{ 'key':k,'title':v['program_title'],'days':v['total_days'],'phases':len(v['phases']),'json_file':f'Beyond_{k}_Internship_180_Day_Program.json','package_file':f'Beyond_{k}_Internship_180_Day_Program_Package.zip'} for k,v in all_programs.items()]},indent=2),encoding='utf-8');files.append(manifest)
master=BASE/'Beyond_All_8_Internship_180_Day_Programs.zip'
with zipfile.ZipFile(master,'w',zipfile.ZIP_DEFLATED) as z:
 for f in files:
  if f.suffix!='.zip' or f.name.endswith('_Package.zip'): z.write(f,f.relative_to(OUT.parent))
print(master);print('programs',len(P),'days',sum(len(x['days']) for x in all_programs.values()),'files',len(files))
